 academic={'satPolicy':'optional','note':L('SAT/ACT optional for admission and scholarship review, independently of an English-proof waiver.','SAT/ACT необязательны для поступления и рассмотрения стипендии; это отдельно от освобождения по английскому.')},
 documents=[L('Secondary-school record and completion evidence, with certified English translation.','Школьные оценки и подтверждение окончания, с заверенным английским переводом.')],
 sources=[S(scad,L('SCAD first-year international guide, revised November 2026','Руководство SCAD для иностранных первокурсников, редакция ноября 2026'),[1,2,3,5],access='web-pdf-read',quote='Otherwise-qualified applicants who do not meet the minimum scores for an ESL waiver may be considered for admission to SCAD.')],
